type AlikeItems = [type: string, count: number];

const groupByType = (items: Item[]): AlikeItems[] => {
  const counts = new Map<string, number>();

  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }

  return [...counts];
};

const basePremiumOfGroup = ([type, count]: AlikeItems): number => {
  if (count === COMPONENT_BLOCK_SIZE) return COMPONENT_BLOCK_PREMIUM;

  return count * BASE_PREMIUMS[type];
};

const basePremiumOf = (items: Item[]): number =>
  groupByType(items)
    .map(basePremiumOfGroup)
    .reduce((total, groupPremium) => total + groupPremium, 0);
